import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.6VU7PjNJ.js";var i=JSON.parse(`{"title":"Usage Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1784988047000}`),a={name:`guide/usage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="usage-guide" tabindex="-1">Usage Guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to “Usage Guide”">​</a></h1><h2 id="basic-gameplay" tabindex="-1">Basic Gameplay <a class="header-anchor" href="#basic-gameplay" aria-label="Permalink to “Basic Gameplay”">​</a></h2><h3 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h3><p>Clear the board without triggering any mines. Reveal all safe squares to win.</p><h3 id="how-to-play" tabindex="-1">How to Play <a class="header-anchor" href="#how-to-play" aria-label="Permalink to “How to Play”">​</a></h3><ul><li><strong>Reveal</strong>: Tap or click a square to reveal it</li><li><strong>Flag</strong>: Long-press (iOS) or right-click (Mac) to flag a suspected mine</li><li><strong>Chord</strong>: Double-tap (iOS) or double-click (Mac) on a revealed number to auto-open adjacent squares (when the correct number of flags are placed)</li><li><strong>Numbers</strong>: Each number shows how many mines are adjacent to that square</li></ul><h3 id="first-click-safety" tabindex="-1">First-Click Safety <a class="header-anchor" href="#first-click-safety" aria-label="Permalink to “First-Click Safety”">​</a></h3><p>Your first reveal will never be a mine. Mines are placed <em>after</em> your first click, excluding the clicked tile.</p><h3 id="difficulty-levels" tabindex="-1">Difficulty Levels <a class="header-anchor" href="#difficulty-levels" aria-label="Permalink to “Difficulty Levels”">​</a></h3><p>Board sizes are optimized per device for the best playing experience:</p><p><img src="/screenshot-iphone-difficulty.png" alt="Minesweeper difficulty levels on iPhone"></p><h4 id="iphone" tabindex="-1">iPhone <a class="header-anchor" href="#iphone" aria-label="Permalink to “iPhone”">​</a></h4><table tabindex="0"><thead><tr><th>Level</th><th>Grid</th><th>Mines</th></tr></thead><tbody><tr><td>Beginner</td><td>10 × 14</td><td>14</td></tr><tr><td>Intermediate</td><td>14 × 22</td><td>45</td></tr><tr><td>Expert</td><td>16 × 30</td><td>99</td></tr></tbody></table><h4 id="ipad" tabindex="-1">iPad <a class="header-anchor" href="#ipad" aria-label="Permalink to “iPad”">​</a></h4><table tabindex="0"><thead><tr><th>Level</th><th>Grid</th><th>Mines</th></tr></thead><tbody><tr><td>Beginner</td><td>16 × 16</td><td>18</td></tr><tr><td>Intermediate</td><td>18 × 16</td><td>55</td></tr><tr><td>Expert</td><td>18 × 24</td><td>99</td></tr></tbody></table><p><img src="/screenshot-ipad-difficulty.png" alt="Minesweeper difficulty levels on iPad"></p><h4 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h4><table tabindex="0"><thead><tr><th>Level</th><th>Grid</th><th>Mines</th></tr></thead><tbody><tr><td>Beginner</td><td>9 × 9</td><td>10</td></tr><tr><td>Intermediate</td><td>16 × 16</td><td>40</td></tr><tr><td>Expert</td><td>30 × 16</td><td>99</td></tr></tbody></table><p><img src="/screenshot-mac-settings.png" alt="Minesweeper on Mac"></p><h2 id="game-controls" tabindex="-1">Game Controls <a class="header-anchor" href="#game-controls" aria-label="Permalink to “Game Controls”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ul><li><strong>Tap</strong>: Reveal a square</li><li><strong>Long press</strong> (0.4s): Toggle flag on/off</li><li><strong>Double-tap</strong>: Chord (auto-reveal adjacent squares)</li></ul><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to “Mac”">​</a></h3><ul><li><strong>Left-click</strong>: Reveal a square</li><li><strong>Right-click</strong>: Toggle flag on/off</li><li><strong>Double-click</strong>: Chord</li><li><strong>Scroll</strong>: Zoom in/out</li></ul><h3 id="keyboard-shortcuts-mac-only" tabindex="-1">Keyboard Shortcuts (Mac only) <a class="header-anchor" href="#keyboard-shortcuts-mac-only" aria-label="Permalink to “Keyboard Shortcuts (Mac only)”">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>⌘N</code></td><td>New game</td></tr><tr><td><code>⌘1</code></td><td>Beginner</td></tr><tr><td><code>⌘2</code></td><td>Intermediate</td></tr><tr><td><code>⌘3</code></td><td>Expert</td></tr><tr><td><code>⌘⇧R</code></td><td>Reveal mines (practice mode)</td></tr></tbody></table><h2 id="timer-scoreboard" tabindex="-1">Timer &amp; Scoreboard <a class="header-anchor" href="#timer-scoreboard" aria-label="Permalink to “Timer &amp; Scoreboard”">​</a></h2><h3 id="timer" tabindex="-1">Timer <a class="header-anchor" href="#timer" aria-label="Permalink to “Timer”">​</a></h3><p>A millisecond-precision timer starts on your first click and stops when the board is cleared or a mine is triggered. The time is displayed in the status bar.</p><h3 id="end-of-game-scoreboard" tabindex="-1">End-of-Game Scoreboard <a class="header-anchor" href="#end-of-game-scoreboard" aria-label="Permalink to “End-of-Game Scoreboard”">​</a></h3><p>When a game ends (win or lose), a scoreboard appears showing:</p><ul><li><strong>Time</strong>: How long the game took</li><li><strong>3BV</strong>: Bechtel&#39;s Board Benchmark Value — a measure of board difficulty</li><li><strong>Clicks</strong>: Breakdown of left clicks, right clicks, and double clicks</li><li><strong>Effective clicks</strong>: Efficiency metric</li></ul><p>On iPhone/iPad, the scoreboard appears as a bottom sheet. On Mac, it appears below the board.</p><h2 id="sound-effects" tabindex="-1">Sound Effects <a class="header-anchor" href="#sound-effects" aria-label="Permalink to “Sound Effects”">​</a></h2><p>Minesweeper includes subtle sound effects for key game events:</p><ul><li><strong>Click</strong>: Tile reveal</li><li><strong>Flag</strong>: Flag placed</li><li><strong>Unflag</strong>: Flag removed</li><li><strong>Boom</strong>: Mine triggered</li><li><strong>Win</strong>: Board cleared</li></ul><p>Toggle sound on or off in <strong>Settings → Sound</strong>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h2><p>Access settings through the gear icon:</p><p><img src="/screenshot-iphone-settings.png" alt="Minesweeper settings on iPhone"></p><p><img src="/screenshot-ipad-settings.png" alt="Minesweeper settings on iPad"></p><ul><li><strong>Language</strong>: Switch between 25 supported languages at runtime — no restart needed</li><li><strong>Game Resolution</strong> (Mac only): Adjust tile size with a slider</li><li><strong>Disable Flagging</strong>: No-flag mode — long-press/right-click opens tiles instead of flagging</li><li><strong>Sound</strong>: Toggle sound effects on/off</li></ul><p>Settings are stored locally on your device using UserDefaults.</p><h2 id="tips-and-tricks" tabindex="-1">Tips and Tricks <a class="header-anchor" href="#tips-and-tricks" aria-label="Permalink to “Tips and Tricks”">​</a></h2><ul><li><strong>First click is always safe</strong> — your first reveal will never be a mine</li><li><strong>Start from corners</strong> — corners have fewer adjacent squares, making deductions easier</li><li><strong>Use flags wisely</strong> — flagging helps you track suspected mines and enables chording</li><li><strong>Look for patterns</strong> — &quot;1-1&quot; and &quot;1-2&quot; patterns reveal mine locations predictably</li><li><strong>Don&#39;t guess until you must</strong> — work through the board systematically before relying on chance</li><li><strong>Use chording</strong> — once you&#39;ve flagged the correct number of mines around a number, double-click/tap to auto-reveal the rest</li></ul>`,45)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};